  Lemma w4sf_round : forall mm mm' sa sb bd4 sb' bd4',
    W4SF' mm sa sb bd4 -> munch [(DST, DST + dcap); (SPF + 216, SPF + 248)] mm mm' -> wmono asegs mm mm' ->
